set-variable.value:
@{
      var auth = context.Request.Headers.GetValueOrDefault("Authorization","");
      if(auth.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase)) {
        return auth.Substring(7).Trim();
      }
      var ak = context.Request.Headers.GetValueOrDefault("api-key","");
      if(!string.IsNullOrEmpty(ak)) {
        return ak;
      }
      return context.Request.Headers.GetValueOrDefault("Ocp-Apim-Subscription-Key","");
    }

@{
          var body = (JObject)context.Variables["reqBody"];
          return body["model"] != null ? body["model"].ToString() : "";
        }

when.set-body:
@{
          var body = (JObject)context.Variables["reqBody"];
          body["model"] = "Kimi-K3.1-Pro";
          var allowed = new string[] { "model", "messages", "temperature", "top_p", "max_tokens", "max_completion_tokens", "stream", "stop", "presence_penalty", "frequency_penalty", "n", "response_format", "tools", "tool_choice", "logprobs", "top_logprobs", "user", "seed", "stream_options", "parallel_tool_calls", "metadata" };
          if (body["max_tokens"] != null && body["max_completion_tokens"] == null) {
            body["max_completion_tokens"] = body["max_tokens"];
            body.Remove("max_tokens");
          }
          // TPM 선반영 폭증 방지: 출력 토큰 상한 4096
          var mct = body["max_completion_tokens"];
          if (mct == null || (int)mct > 4096) { body["max_completion_tokens"] = 4096; }
          if (body["parallel_tool_calls"] != null && body["tools"] == null) { body.Remove("parallel_tool_calls"); }
          var toRemove = new System.Collections.Generic.List<string>();
          foreach (var prop in body.Properties()) { bool ok = false; foreach (var a in allowed) { if (prop.Name == a) { ok = true; break; } } if (!ok) { toRemove.Add(prop.Name); } }
          foreach (var rm in toRemove) { body.Remove(rm); }
          return body.ToString(Newtonsoft.Json.Formatting.None);
        }
